import { describe, test, expect, beforeEach, afterEach } from 'bun:test';
import { existsSync, readFileSync } from 'node:fs';
import { join, resolve } from 'node:path';

import { SUPPORTED_CONTRACTS, KitsudenAdapter } from '../src/index.js';
import type { KitsudenGameBlock } from '../src/index.js';

/**
 * CONTRACT test with Kitsuden: the adapter against the API's REAL responses, not against
 * objects written by hand.
 *
 * The file is generated by the kons repository mounting the real routers
 * (`tests/unit/inti-contract.test.ts` there), which also checks on every run that the API still
 * answers this way. The canonical copy lives in the Kitsuden core:
 *
 *   <kitsuden>/packages/shared/contracts/inti/reference-responses.json
 *
 * and there is a copy here (`tests/contract/`) so this suite works without the Kitsuden repo next
 * to it. If the repo IS there (`KITSUDEN_REPO=/path`, or by default `../kitsuden`,
 * `../kitsuden-final` or `../cms` next to this repo, the first that has it), the canonical one is
 * used and the copy is required to be identical: that way an API change that was not brought here
 * does not go unnoticed.
 */

interface Case {
    name: string;
    contract: string;
    template: string;
    method: string;
    path: string;
    request?: any;
    status: number;
    body: any;
}
interface Reference {
    kitsuden: string;
    contracts: Record<string, number>;
    cases: Case[];
}

const RELATIVE = join('packages', 'shared', 'contracts', 'inti', 'reference-responses.json');
const COPY = join(import.meta.dir, 'contract', 'reference-responses.json');
const ROOT = resolve(import.meta.dir, '..', '..', '..', '..');
const REPOS = process.env.KITSUDEN_REPO
    ? [process.env.KITSUDEN_REPO]
    : [join(ROOT, 'kitsuden-final'), join(ROOT, 'kitsuden'), join(ROOT, 'cms')];
const CANONICAL = REPOS.map((repo) => join(repo, RELATIVE)).find(existsSync) ?? join(REPOS[0], RELATIVE);
const HAS_CANONICAL = existsSync(CANONICAL);

const read = (path: string) => JSON.parse(readFileSync(path, 'utf8')) as Reference;
const REF = read(HAS_CANONICAL ? CANONICAL : COPY);
const caseNamed = (name: string): Case => {
    const c = REF.cases.find((x) => x.name === name);
    if (!c) throw new Error(`The case «${name}» is missing from the reference responses`);
    return c;
};

const ENDPOINT = 'https://cms.test';
const TOKEN = 'kitsuden_agent_tests';
const GAME = caseNamed('gameById').body;
const PAGE = caseNamed('pageById').body;

// ── fetch served from the reference responses ──────────────────────────────

let calls: Array<{ method: string; path: string; body?: any }> = [];
let originalFetch: typeof fetch;
let originalError: typeof console.error;

/** An id of the seed (uuid or game block id): in a template any one fits */
const SEED_ID = /^([0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}|cd-[a-z]+-\d+)$/;

/** READS answer the state before any write (the GET cases) */
function answerFromReference(method: string, path: string): Case | undefined {
    const templateOf = (c: Case) => new URL(c.path, ENDPOINT).pathname;
    // Exact match of path (the seed's ids) and method
    const exact = REF.cases.find((c) => c.method === method && templateOf(c) === path);
    if (exact) return exact;
    // Writes on ids the adapter got from another response (e.g. the created block): by template
    const segments = path.split('/');
    return REF.cases.find((c) => {
        if (c.method !== method) return false;
        const ref = templateOf(c).split('/');
        return ref.length === segments.length && ref.every((s, i) => s === segments[i] || SEED_ID.test(s));
    });
}

beforeEach(() => {
    calls = [];
    originalFetch = globalThis.fetch;
    originalError = console.error;
    console.error = () => {};
    globalThis.fetch = (async (input: any, init?: RequestInit) => {
        const url = new URL(String(input));
        const method = init?.method ?? 'GET';
        calls.push({ method, path: url.pathname, body: init?.body ? JSON.parse(String(init.body)) : undefined });
        const c = answerFromReference(method, url.pathname);
        if (!c) return new Response(JSON.stringify({ error: `no case for ${method} ${url.pathname}` }), { status: 599 });
        return new Response(JSON.stringify(c.body), {
            status: c.status,
            headers: { 'Content-Type': 'application/json' }
        });
    }) as typeof fetch;
});

afterEach(() => {
    globalThis.fetch = originalFetch;
    console.error = originalError;
});

const adapter = () => new KitsudenAdapter({ endpoint: ENDPOINT, token: TOKEN });
const writes = () => calls.filter((l) => l.method !== 'GET');

// ═══════════════════════════════════════════════════════════════════════════

describe('the reference file', () => {
    test.skipIf(!HAS_CANONICAL)("the copy in tests/contract/ is identical to Kitsuden's canonical one", () => {
        // If it fails: copy <kitsuden>/packages/shared/contracts/inti/reference-responses.json
        // to tests/contract/ and check that the rest of this suite stays green.
        expect(read(COPY)).toEqual(read(CANONICAL));
    });

    test('covers every route the adapter uses', () => {
        const templates = REF.cases.map((c) => c.template);
        for (const needed of [
            'GET /api/version',
            'GET /api/games/slug/:slug',
            'GET /api/games/:id',
            'GET /api/page-builder/pages/:id',
            'GET /api/page-builder/block-types',
            'PATCH /api/games/:id/blocks/:blockId/editorial',
            'PUT /api/games/:id/blocks/order',
            'POST /api/page-builder/pages/:pageId/blocks',
            'PATCH /api/page-builder/blocks/:id',
            'POST /api/page-builder/pages/:pageId/blocks/reorder',
            'POST /api/page-builder/blocks/:id/duplicate',
            'DELETE /api/page-builder/blocks/:id'
        ]) {
            expect(templates).toContain(needed);
        }
    });

    test('this version of the adapter supports the contracts that Kitsuden declares', async () => {
        const api = await adapter().checkCompatibility();
        expect(api?.version).toBe(REF.kitsuden);
        expect(api?.contracts).toEqual(REF.contracts);
        for (const [name, [min, max]] of Object.entries(SUPPORTED_CONTRACTS)) {
            const declared = REF.contracts[name];
            expect(declared, name).toBeGreaterThanOrEqual(min);
            expect(declared, name).toBeLessThanOrEqual(max);
        }
    });
});

describe('reading: the adapter understands the real responses', () => {
    test('GET /api/games/slug/:slug → index rule shared with the site (hidden ones out, editorial.order ?? order)', async () => {
        const game = await adapter().getGame(caseNamed('gameBySlug').path.split('/').pop()!);
        expect(game.id).toBe(`game:${GAME.id}`);

        // Seed: table (order 0, editorial.order 2), tier (order 1, title edited),
        // dex (hidden), map (order 3) → visible: tier, table, map
        expect(game.blocks.map((b) => b.id)).toEqual(['cd-tier-2', 'cd-table-1', 'cd-map-4']);
        const tier = game.blocks[0] as KitsudenGameBlock;
        expect(tier.data.title).toBe("The team's tier list");
        expect(tier.original?.title).toBe('Tier list');
        expect(tier.editorial).toEqual({ title: "The team's tier list" });
        expect(game.blocks.map((b) => b.meta?.index)).toEqual([0, 1, 2]);
        expect(game.seo?.description).toBe(GAME.excerpt);
    });

    test('GET /api/games/:id gives the same result as by slug', () => {
        const a = adapter();
        expect(a.parseGame(caseNamed('gameById').body)).toEqual(a.parseGame(caseNamed('gameBySlug').body));
    });

    test('GET /api/page-builder/pages/:id and by slug → same page, blocks by sortOrder', async () => {
        const a = adapter();
        const byId = await a.getPage(PAGE.id);
        const bySlug = await a.getPage(PAGE.slug);
        expect(bySlug).toEqual(byId);
        expect(byId.title).toBe(PAGE.title);
        // The API already hides the invisible one; hero (0) and text (10) remain
        expect(byId.blocks.map((b) => b.type)).toEqual(['hero', 'text']);
        expect(byId.blocks[0].data.headline).toBe('Hello');
    });

    test('GET /api/page-builder/pages → listPages (sitemap)', async () => {
        const pages = await adapter().listPages();
        expect(pages).toEqual([{ slug: PAGE.slug, title: PAGE.title, updatedAt: PAGE.updatedAt }]);
    });

    test('GET /api/page-builder/block-types → palette (wrapped in { blockTypes }) and introspection', async () => {
        const a = adapter();
        const types = await a.blockTypes();
        expect(types.length).toBe(caseNamed('blockTypes').body.blockTypes.length);
        expect(types.map((t) => t.type)).toContain('hero');

        const schema = await a.introspect();
        const hero = schema.collections.find((c) => c.blockType === 'hero');
        expect(hero?.fields.find((f) => f.name === 'headline')).toMatchObject({ type: 'string', required: true });
        expect((await a.generatorBlockTypes()).length).toBe(types.length);
    });
});

describe('writing: the routes, bodies and responses of the contract', () => {
    test('page updateBlockField → GET /pages/:id + PATCH /blocks/:id with the contract body', async () => {
        const request = caseNamed('editBlock').request;
        const r = await adapter().updateBlockField(PAGE.id, 0, 'headline', request.content.headline);
        expect(r.success).toBe(true);
        const patch = writes()[0];
        expect(`${patch.method} ${patch.path}`).toBe(`PATCH ${new URL(caseNamed('editBlock').path, ENDPOINT).pathname}`);
        expect(patch.body).toEqual(request);
    });

    test('page moveBlock → POST reorder permuting the existing sortOrders (the contract body)', async () => {
        const r = await adapter().moveBlock(PAGE.id, 0, 1);
        expect(r.success).toBe(true);
        expect(writes()).toEqual([
            {
                method: 'POST',
                path: new URL(caseNamed('reorderBlocks').path, ENDPOINT).pathname,
                body: caseNamed('reorderBlocks').request
            }
        ]);
    });

    test('insertBlock at the end → POST /pages/:id/blocks (201) without reordering', async () => {
        const request = caseNamed('createBlock').request;
        const r = await adapter().insertBlock(PAGE.id, 2, request.type, request.content);
        expect(r.success).toBe(true);
        expect(r.value).toEqual({ id: caseNamed('createBlock').body.id, type: request.type });
        expect(writes().map((l) => `${l.method} ${l.path}`)).toEqual([
            `POST ${new URL(caseNamed('createBlock').path, ENDPOINT).pathname}`
        ]);
        expect(writes()[0].body).toEqual(request);
    });

    test('duplicateBlock of the last one → POST /blocks/:id/duplicate (201)', async () => {
        const r = await adapter().duplicateBlock(PAGE.id, 1);
        expect(r.success).toBe(true);
        expect(r.value).toEqual({ id: caseNamed('duplicateBlock').body.id });
    });

    test('removeBlock → DELETE /blocks/:id', async () => {
        const r = await adapter().removeBlock(PAGE.id, 1);
        expect(r.success).toBe(true);
        expect(writes().map((l) => `${l.method} ${l.path}`)).toEqual([
            `DELETE ${new URL(caseNamed('deleteBlock').path, ENDPOINT).pathname}`
        ]);
    });

    test('game updateBlock → re-reads by uuid and PATCHes the editorial layer with the contract body', async () => {
        // index 2 = cd-map-4 (see the index rule above)
        const r = await adapter().updateBlock(`game:${GAME.id}`, 2, caseNamed('editGameBlock').request);
        expect(r.success).toBe(true);
        expect(r.value).toEqual(caseNamed('editGameBlock').body);
        expect(calls.filter((l) => l.method === 'GET').map((l) => l.path)).toContain(`/api/games/${GAME.id}`);
        expect(writes()).toEqual([
            {
                method: 'PATCH',
                path: new URL(caseNamed('editGameBlock').path, ENDPOINT).pathname,
                body: caseNamed('editGameBlock').request
            }
        ]);
    });

    test('game moveBlock → PUT /blocks/order with ALL the ids (hidden ones included)', async () => {
        const r = await adapter().moveBlock(`game:${GAME.id}`, 1, 0);
        expect(r.success).toBe(true);
        const put = writes()[0];
        expect(`${put.method} ${put.path}`).toBe(`PUT ${new URL(caseNamed('reorderGameBlocks').path, ENDPOINT).pathname}`);
        expect([...put.body.ids].sort()).toEqual([...caseNamed('reorderGameBlocks').request.ids].sort());
        // table goes in front of tier; the hidden one keeps its slot
        expect(put.body.ids).toEqual(['cd-table-1', 'cd-tier-2', 'cd-dex-3', 'cd-map-4']);
    });

    test('game removeBlock = hide (PATCH editorial { hidden: true }), never DELETE', async () => {
        const r = await adapter().removeBlock(`game:${GAME.id}`, 0);
        expect(r.success).toBe(true);
        expect(writes()).toEqual([
            { method: 'PATCH', path: `/api/games/${GAME.id}/blocks/cd-tier-2/editorial`, body: { hidden: true } }
        ]);
    });
});
